}

test "t8" {
    assert (single(range(1)) == 0);;
}

test "t9" {
    assert (single(x for x in [1]) == 1);;
}

test "t10" {
    assert (single(iter([x for x in range(1)])) == 0);;
}

test "t11" {
    assert (single('a') == 'a');;
}

test "t12" {
    assert (single([1]) == 1);;
}
